        ['abbr' => 'YC', 'title' => 'Yoga Club', 'convenor' => 'Club Convenor: Mr. Gnanasekararan M', 'sections' => [['heading' => 'Message', 'items' => [['p' => 'Our Yoga Club is dedicated to promoting a healthy body, peaceful mind, and balanced lifestyle through the regular practice of yoga and meditation. Let us come together to spread awareness about the importance of yoga, encourage healthy habits, and build a community rooted in peace, positivity, and harmony.'], ['p' => '“Yoga is not just an exercise; it is a way of life.”'], ['p' => 'Let us breathe together, grow together, and live healthier together with peace and positivity, Yoga Club Team.']]], ['heading' => 'Vision', 'items' => [['p' => 'To promote a healthy, peaceful, and balanced lifestyle through the practice of yoga, meditation, and mindfulness. We aim to create a positive and supportive community that nurtures physical fitness, mental well-being, emotional balance, and spiritual growth. Our vision is to inspire everyone to embrace yoga as a way of life and build a healthier, happier, and more harmonious society.']]], ['heading' => 'Mission', 'items' => [['p' => 'To promote the regular practice of yoga, meditation, and breathing techniques to improve physical health, mental peace, and emotional well-being. Our mission is to create awareness about the benefits of yoga, encourage healthy lifestyle habits, and provide a supportive environment where individuals can grow together in health, harmony, and happiness. We strive to make yoga accessible to everyone and inspire people to incorporate yoga into their daily lives for a healthier and more peaceful society.']]], ['heading' => 'Motto', 'items' => [['p' => '“Healthy Body, Peaceful Mind, Harmonious Life.”']]], ['heading' => 'Slogan', 'items' => [['p' => '“Embrace Yoga, Enhance Life!”']]], ['heading' => 'Objectives', 'items' => [['list' => ['Promote Physical Health: Encourage regular yoga practice to improve flexibility, strength, posture, and overall fitness.', 'Enhance Mental Well-being: Promote mental peace, concentration, mindfulness, and stress management through yoga and meditation.', 'Develop Healthy Habits: Encourage members to adopt a healthy lifestyle through regular exercise, proper breathing, and self-discipline.', 'Create Yoga Awareness: Educate people about the importance and benefits of yoga in daily life.', 'Improve Emotional Balance: Help individuals develop patience, self-confidence, positivity, and emotional stability.', 'Encourage Community Participation: Bring people together through yoga sessions, workshops, demonstrations, and awareness programmes.', 'Promote Holistic Wellness: Support the overall development of physical, mental, emotional, and spiritual well-being.', 'Make Yoga Accessible to All: Motivate people of all ages and backgrounds to practise yoga according to their abilities.', 'Build Discipline and Harmony: Cultivate unity, cooperation, respect, and a sense of responsibility among club members.', 'Spread the Message of Yoga: Inspire individuals to make yoga a part of their daily lives and contribute to a healthier and more peaceful society.']]]], ['heading' => 'Our Goal', 'items' => [['p' => 'To build a healthy, mindful, and harmonious community through the regular practice of yoga.']]]]],
        ['abbr' => 'EL', 'title' => 'Electoral Literacy Club (ELC)', 'convenor' => 'Club Convenor: Mr. Gnanasekararan M', 'sections' => [['heading' => 'Message', 'items' => [['p' => 'The Electoral Literacy Club aims to create awareness among students about democracy, electoral rights, voter registration, and the importance of voting. It encourages young citizens to become informed, responsible, and ethical voters. Let us learn about our electoral system, understand our voting rights, and actively participate in strengthening our democracy.']]], ['heading' => 'Vision', 'items' => [['p' => 'To develop informed, responsible, and empowered citizens who actively participate in the democratic process.']]], ['heading' => 'Mission', 'items' => [['p' => 'To promote electoral literacy and democratic values among students and citizens through awareness programmes, interactive activities, and voter education.']]], ['heading' => 'Motto', 'items' => [['p' => '“Learn Democracy. Lead Democracy.”']]], ['heading' => 'Slogan', 'items' => [['p' => '“My Vote, My Right, My Future.”']]], ['heading' => 'Objectives', 'items' => [['list' => ['To create awareness about democracy and the electoral process.', 'To educate students about voter registration and voting rights.', 'To help eligible students register as voters when they turn 18.', 'To create awareness about Electronic Voting Machines (EVMs) and Voter Verifiable Paper Audit Trail (VVPAT).', 'To encourage ethical, informed, and responsible voting.', 'To promote electoral awareness among students and the wider community.', 'To develop active and responsible citizens who participate in democracy.']]]]]],
        ['abbr' => 'YR', 'title' => 'Youth Red Cross (YRC)', 'convenor' => 'Club Convenor: Mr. Gnanasekararan M', 'sections' => [['heading' => 'Message', 'items' => [['p' => 'Youth Red Cross plays an important role in channelizing and guiding the youth energy in the cause of humanitarian action. The involvement and contribution of the volunteers to the noble cause of serving the society has been significant. The activities of YRC include Blood Donation & Identification Camp, Promotion of Peace and Harmony, Awareness program on Health and Hygiene and Basic First Aid.']]], ['heading' => 'Vision', 'items' => [['p' => 'The purpose of Youth Red Cross is to protect life and health and to ensure respect for the human being. It promotes mutual understanding, Co-operation amongst all people.']]], ['heading' => 'Mission', 'items' => [['p' => 'The mission of Youth Red Cross is to alleviate human suffering in the face of emergencies. To provide relief in all times of disasters and promoting care of vulnerable people and communities. It helps Youth to aware about their role and responsibility towards Society.']]], ['heading' => 'Motto', 'items' => [['p' => '“I Serve” or “Service to Society”']]], ['heading' => 'Slogan', 'items' => [['p' => '“Youth for Humanity, Service for All.”']]], ['heading' => 'Objectives', 'items' => [['p' => 'The main objective of the Youth Red Cross is to develop young people’s spirit of service, humanitarian values, and responsibility towards society. The overall objectives are:'], ['list' => ['Promotion of Health: To protect and improve the health of individuals and communities.', 'Service to Humanity: To develop a spirit of service and help people in need without discrimination.', 'Relief in Emergencies: To assist people affected by natural disasters, accidents, and other emergencies.', 'Development of Leadership: To develop leadership qualities, discipline, teamwork, and a sense of responsibility among youth.', 'First Aid Training: To educate students in first aid and basic life-saving skills.', 'Community Service: To encourage participation in blood donation awareness, health camps, cleanliness drives, and other social service activities.', 'International Friendship: To promote friendship, peace, mutual understanding, and cooperation among people.', 'Humanitarian Values: To develop kindness, compassion, respect, and concern for others.', 'Disease Prevention: To create awareness about communicable diseases, hygiene, sanitation, and healthy living.', 'Environmental Protection: To encourage environmental awareness and the protection of nature.']]]]]],
        ['abbr' => 'RR', 'title' => 'Red Ribbon Club (RRC)', 'convenor' => 'Club Convenor: Mr. Gnanasekararan M', 'sections' => [['heading' => 'Message', 'items' => [['p' => 'The Red Ribbon Club aims to create awareness among youth about HIV/AIDS prevention, healthy lifestyles, and the importance of voluntary blood donation. It encourages young people to become responsible citizens, spread health awareness, and promote compassion, equality, and respect for all. Through education, participation, and community service, the RRC strives to build a healthy, informed, and stigma-free society.'], ['p' => '“Be aware, be responsible, donate blood, and spread love—not stigma.”']]], ['heading' => 'Vision', 'items' => [['p' => 'To create a healthy, informed, and responsible youth community free from the stigma and discrimination associated with HIV/AIDS, while promoting healthy lifestyles and voluntary blood donation.']]], ['heading' => 'Mission', 'items' => [['list' => ['To create awareness among youth about HIV/AIDS, its prevention, and treatment.', 'To promote voluntary blood donation and encourage a culture of regular blood donation.', 'To educate students about reproductive and sexual health.', 'To eliminate stigma and discrimination against people living with HIV/AIDS.', 'To develop youth leadership and peer educators to spread health awareness.', 'To encourage healthy lifestyles, responsible behaviour, and community participation.']]]], ['heading' => 'Motto', 'items' => [['p' => '“Awareness, Prevention, Blood Donation, and Compassion.”']]], ['heading' => 'Slogan', 'items' => [['p' => '“Spread Awareness, Save Lives, Stop HIV Stigma.”']]], ['heading' => 'Objectives', 'items' => [['list' => ['To create awareness among students about HIV/AIDS and its prevention.', 'To promote voluntary blood donation and encourage safe blood donation practices.', 'To educate youth about sexual and reproductive health.', 'To eliminate stigma and discrimination against people living with HIV/AIDS.', 'To encourage healthy lifestyles and responsible behaviour among young people.', 'To develop leadership skills and promote peer education among students.', 'To disseminate accurate information about HIV testing, treatment, and prevention.', 'To encourage youth participation in health awareness programmes and community service.', 'To promote compassion, equality, and respect for people affected by HIV/AIDS.', 'To empower young people to become health ambassadors in society.']]]]]],
        ['abbr' => 'SD', 'title' => 'Sustainable Development Goals (SDG) Club', 'convenor' => 'Club Convenor: Dr Jenifer Jincy T', 'sections' => [['heading' => 'About', 'items' => [['p' => 'The Sustainable Development Goals (SDG) Club aims to create awareness among students about the 17 Sustainable Development Goals established by the United Nations. The club encourages students to adopt sustainable practices, promote environmental protection, reduce inequalities, and contribute to social and economic development. Through awareness programmes, campaigns, workshops, and community initiatives, the club nurtures responsible citizens committed to building a sustainable and inclusive future.']]], ['heading' => 'Vision', 'items' => [['p' => 'To foster a sustainable, inclusive, and equitable society by empowering students to become responsible citizens who contribute to achieving the Sustainable Development Goals.']]], ['heading' => 'Mission', 'items' => [['p' => 'To create awareness of sustainable development among students and encourage active participation in environmental conservation, social responsibility, equality, and community development through educational activities and practical initiatives.']]], ['heading' => 'Objectives', 'items' => [['list' => ['To create awareness about the 17 Sustainable Development Goals of the United Nations.', 'To promote environmental conservation, waste management, and responsible use of natural resources.', 'To encourage sustainable lifestyles and responsible consumption among students.', 'To promote gender equality, social inclusion, and equal opportunities for all.', 'To organise seminars, workshops, awareness campaigns, and other activities related to sustainable development.', 'To encourage community participation through outreach programmes and social service activities.', 'To develop leadership, teamwork, and problem-solving skills among students.', 'To inspire students to take meaningful action towards building a greener, healthier, and more sustainable future.']]]]]],
        ['abbr' => 'SM', 'title' => 'Stock Market Club', 'convenor' => 'Club Convenor: Mr. Lathi T M', 'sections' => [['heading' => 'About', 'items' => [['p' => 'The Stock Market Club aims to develop students’ financial literacy and awareness of stock markets, investments, and economic trends. The club provides a platform for students to understand the fundamentals of stock trading, investment strategies, risk management, and financial planning through interactive sessions, workshops, discussions, and simulated trading activities. It encourages informed financial decision-making, analytical thinking, and responsible investment practices.']]], ['heading' => 'Vision', 'items' => [['p' => 'To empower students with financial knowledge and investment awareness, fostering responsible investors and financially informed citizens.']]], ['heading' => 'Mission', 'items' => [['list' => ['To create awareness about stock markets and financial systems.', 'To develop students’ understanding of investment principles and financial planning.', 'To promote analytical thinking and informed decision-making.', 'To provide practical learning opportunities through stock market simulations and expert sessions.', 'To encourage ethical, disciplined, and responsible investment practices.']]]], ['heading' => 'Objectives', 'items' => [['list' => ['To introduce students to the basics of the stock market, shares, and securities.', 'To create awareness of investment opportunities, mutual funds, and other financial instruments.', 'To familiarise students with stock exchanges such as NSE and BSE.', 'To develop skills in market analysis, financial research, and decision-making.', 'To provide hands-on learning through virtual stock market trading and investment simulations.', 'To organise seminars, workshops, quizzes, and expert talks on financial literacy.', 'To educate students about investment risks, fraud prevention, and investor protection.', 'To encourage responsible financial habits and long-term financial planning.']]]]]],
